package com.hms.appointments;
import com.hms.tenancy.*; import java.time.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/appointment-search") public class AppointmentSearchController {private final TenantRepository tenants;private final AppointmentRepository appointments;private final PatientRepository patients;public AppointmentSearchController(TenantRepository t,AppointmentRepository a,PatientRepository p){tenants=t;appointments=a;patients=p;} @GetMapping public List<AppointmentDto> search(@PathVariable String tenantSlug,@RequestParam(required=false) String patientName,@RequestParam(required=false) LocalDate date,@RequestParam(required=false) AppointmentStatus status){UUID tenant=tenant(tenantSlug);Map<UUID,Patient> byId=patients.findAllByTenantId(tenant).stream().collect(java.util.stream.Collectors.toMap(Patient::getId,x->x));return appointments.findAllByTenantIdOrderByStartsAtAsc(tenant).stream().filter(a->status==null||a.getStatus()==status).filter(a->date==null||a.getStartsAt().toLocalDate().equals(date)).filter(a->patientName==null||byId.get(a.getPatientId()).getFullName().toLowerCase().contains(patientName.toLowerCase())).map(a->AppointmentDto.from(a,byId.get(a.getPatientId()))).toList();} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
